import React, {useState, useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {CodeBlock,CodeBlockActions,CodeBlockCopyButton,CodeBlockContent} from '../../registry/cadence/code-block';
import {CadenceProvider} from '../../registry/cadence/lib/provider';
window.proof={events:[],refs:[],cleanups:[]};
function Fixture(){
 const [version,setVersion]=useState(0); const [mode,setMode]=useState('full');
 window.changeRef=()=>setVersion(v=>v+1); window.changeMode=setMode;
 const ref=useCallback(node=>{if(node)window.proof.refs.push(version);return ()=>window.proof.cleanups.push(version)},[version]);
 const handler=e=>{window.proof.events.push({type:e.type,native:e.nativeEvent===window.sentEvent,current:e.currentTarget.dataset.slot});e.preventDefault();e.stopPropagation()};
 return <CadenceProvider mode={mode}><CodeBlock><CodeBlockActions ref={ref} tabIndex={0} onAnimationStart={handler} onDrag={handler} onDragStart={handler} onDragEnd={handler}><CodeBlockCopyButton value="source" /></CodeBlockActions><CodeBlockContent>source</CodeBlockContent></CodeBlock></CadenceProvider>
}
createRoot(document.getElementById('root')).render(<Fixture/>);

