import {chromium,expect} from '@playwright/test';
import {writeFileSync} from 'node:fs';
const browser=await chromium.launch({channel:'msedge',headless:true});
const page=await browser.newPage();
await page.goto('http://127.0.0.1:3154');
const actions=page.locator('[data-slot="code-block-actions"]');
await actions.waitFor();
const reports=[];
for(const mode of ['full','reduced','none']){
 await page.evaluate(mode=>window.changeMode(mode),mode);
 await expect(actions).toHaveAttribute('data-motion',mode);
 await actions.focus();
 await expect.poll(()=>actions.evaluate(e=>Number(getComputedStyle(e).opacity))).toBe(1);
 reports.push(await page.evaluate(()=>{
 const node=document.querySelector('[data-slot="code-block-actions"]');
 for(const type of ['animationstart','drag','dragstart','dragend']){window.sentEvent=new Event(type,{bubbles:true,cancelable:true});node.dispatchEvent(window.sentEvent);if(!window.sentEvent.defaultPrevented)throw Error('cancellation lost')}
 return {mode:node.dataset.motion,events:window.proof.events.slice(-4)};
 }));
}
await page.evaluate(()=>window.changeRef());
await expect.poll(()=>page.evaluate(()=>window.proof.cleanups.length)).toBe(1);
await expect(actions).toBeFocused();
expect(await page.evaluate(()=>window.proof.refs)).toEqual([0,1]);
expect(reports.every(r=>r.events.length===4&&r.events.every(e=>e.native&&e.current==='code-block-actions'))).toBe(true);
await page.screenshot({path:'.cache/native-div-floating-production.png'});
writeFileSync('.cache/native-div-floating-production.json',JSON.stringify(reports,null,2));
await browser.close();
console.log('Floating Actions production Vite/Edge: 3 modes, 12 exact native events, focused ref handoff passed');
